Decrypter.java:

import org.apache.commons.codec.binary.Base64;
import javax.crypto.Cipher;
import java.io.*;
import java.security.KeyFactory;
import java.security.PrivateKey;
import java.security.spec.PKCS8EncodedKeySpec;

public class Decrypter {
String keyFileName;

public Decrypter(String keyFileName) {
 this.keyFileName = keyFileName;
}

public String rsaDecrypt(String str) throws Exception {
 PrivateKey privateKey = readPrivateKeyFromFile(keyFileName);
 Cipher cipher = Cipher.getInstance("RSA");

 cipher.init(Cipher.DECRYPT_MODE, privateKey);
 byte[] dec = Base64.decodeBase64(str);
 byte[] utf8 = cipher.doFinal(Base64.decodeBase64(dec));
 return Base64.encodeBase64String(utf8);

}

private PrivateKey readPrivateKeyFromFile(String keyFileName) throws Exception {
 File filePrivateKey = new File(keyFileName);
 FileInputStream fis = new FileInputStream(keyFileName);
 byte[] encodedPrivateKey = new byte[(int) filePrivateKey.length()];
 fis.read(encodedPrivateKey);
 fis.close();

 KeyFactory keyFactory = KeyFactory.getInstance("RSA");
 PKCS8EncodedKeySpec privateKeySpec = new PKCS8EncodedKeySpec(
 encodedPrivateKey);
 PrivateKey privateKey = keyFactory.generatePrivate(privateKeySpec);
 return privateKey;
}
}

accepted answers:
You can utilize the fact, that (N-1) % N == -1.

Thus, (65536 * a) % 65537 == -a % 65537.
Also, -a % 65537 == -a + 1 (mod 65536), when 0 is interpreted as 65536

uint16_t fastmod65537(uint16_t a, uint16_t b)
{
    uint32_t c;
    uint16_t hi, lo;
    if (a == 0)
        return -b + 1;
    if (b == 0)
        return -a + 1;

    c = (uint32_t)a * (uint32_t)b;
    hi = c >> 16;
    lo = c;
    if (lo > hi)
        return lo-hi;
    return lo-hi+1;
}
The only problem here is if hi == lo, the result would be 0. Luckily a test suite confirms, that it actually can't be...

int main()
{
    uint64_t a, b;
    for (a = 1; a <= 65536; a++)
       for (b = 1; b <= 65536; b++)
        { 
            uint64_t c = a*b;
            uint32_t d = (c % 65537) & 65535;
            uint32_t e = m(a & 65535, b & 65535);
            if (d != e)
                printf("a * b % 65537 != m(%d, %d) real=%d m()=%d\n",
                       (uint32_t)a, (uint32_t)b, d, e);
        }
    }
Output: none

